"use client"

import * as React from "react"
import { cn } from "cn"
import { SearchIcon, XIcon } from "lucide-react"

import { Button } from "@tecton/react/components/button"
import {
  InputGroup,
  InputGroupAddon,
  InputGroupInput,
} from "@tecton/react/components/input-group"
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@tecton/react/components/select"
import { Chip, ChipGroup, ChipList } from "@tecton/react/tecton/chip"

import { fields, statusMeta, typeMeta } from "../data"
import type { WellStatus, WellType } from "../data"

export type WellsFilter = {
  query: string
  field: string
  type: WellType | "all"
  statuses: WellStatus[]
}

export const emptyFilter: WellsFilter = {
  query: "",
  field: "all",
  type: "all",
  statuses: [],
}

const allStatuses = Object.keys(statusMeta) as WellStatus[]

type WellsFilterBarProps = Omit<React.ComponentProps<"div">, "onChange"> & {
  value: WellsFilter
  onChange: (next: WellsFilter) => void
  /** Number of rows matching the current filter. */
  resultCount?: number
}

function WellsFilterBar({
  className,
  value,
  onChange,
  resultCount,
  ...props
}: WellsFilterBarProps) {
  const set = <TKey extends keyof WellsFilter>(
    key: TKey,
    next: WellsFilter[TKey]
  ) => onChange({ ...value, [key]: next })

  const active =
    value.query.trim() !== "" ||
    value.field !== "all" ||
    value.type !== "all" ||
    value.statuses.length > 0

  return (
    <div
      data-slot="wells-filter-bar"
      className={cn("flex flex-col gap-3", className)}
      {...props}
    >
      <div className="flex flex-col gap-3 md:flex-row md:items-end">
        <InputGroup className="md:max-w-xs">
          <InputGroupInput
            aria-label="Search wells"
            placeholder="Search by name, rig or operator…"
            value={value.query}
            onChange={(event) => set("query", event.target.value)}
          />
          <InputGroupAddon align="inline-start">
            <SearchIcon aria-hidden />
          </InputGroupAddon>
        </InputGroup>
        <Select
          aria-label="Field"
          className="md:w-48"
          value={value.field}
          onChange={(key) => set("field", String(key))}
        >
          <SelectTrigger>
            <SelectValue />
          </SelectTrigger>
          <SelectContent>
            <SelectItem id="all" textValue="All fields">
              All fields
            </SelectItem>
            {fields.map((field) => (
              <SelectItem key={field} id={field} textValue={field}>
                {field}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
        <Select
          aria-label="Well type"
          className="md:w-44"
          value={value.type}
          onChange={(key) => set("type", String(key) as WellsFilter["type"])}
        >
          <SelectTrigger>
            <SelectValue />
          </SelectTrigger>
          <SelectContent>
            <SelectItem id="all" textValue="All types">
              All types
            </SelectItem>
            {(Object.keys(typeMeta) as WellType[]).map((type) => (
              <SelectItem key={type} id={type} textValue={typeMeta[type]}>
                {typeMeta[type]}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
        {active && (
          <Button
            variant="ghost"
            size="sm"
            className="md:ms-auto"
            onPress={() => onChange(emptyFilter)}
          >
            <XIcon /> Clear filters
          </Button>
        )}
      </div>

      <div className="flex flex-wrap items-center gap-2">
        <span className="text-xs text-muted-foreground">Status</span>
        <ChipGroup
          aria-label="Status filters"
          selectionMode="multiple"
          selectedKeys={value.statuses}
          onSelectionChange={(keys) =>
            set(
              "statuses",
              keys === "all"
                ? allStatuses
                : allStatuses.filter((status) => keys.has(status))
            )
          }
        >
          <ChipList>
            {allStatuses.map((status) => {
              const selected = value.statuses.includes(status)
              return (
                <Chip
                  key={status}
                  id={status}
                  textValue={statusMeta[status].label}
                  size="md"
                  variant={selected ? statusMeta[status].color : "secondary"}
                  appearance={selected ? "solid" : "outline"}
                >
                  {statusMeta[status].label}
                </Chip>
              )
            })}
          </ChipList>
        </ChipGroup>
        {value.statuses.length > 0 && (
          <ChipGroup
            aria-label="Active status filters"
            className="ms-auto"
            onRemove={(keys) =>
              set(
                "statuses",
                value.statuses.filter((status) => !keys.has(status))
              )
            }
          >
            <ChipList>
              {value.statuses.map((status) => (
                <Chip
                  key={status}
                  id={status}
                  textValue={statusMeta[status].label}
                >
                  {statusMeta[status].label}
                </Chip>
              ))}
            </ChipList>
          </ChipGroup>
        )}
        {typeof resultCount === "number" && (
          <span className="ms-auto font-mono text-xs text-muted-foreground tabular-nums">
            {resultCount} {resultCount === 1 ? "well" : "wells"}
          </span>
        )}
      </div>
    </div>
  )
}

export { WellsFilterBar }
export type { WellsFilterBarProps }

"use client"

import * as React from "react"
import {
  createColumnHelper,
  createPaginatedRowModel,
  createSortedRowModel,
  rowPaginationFeature,
  rowSelectionFeature,
  rowSortingFeature,
  tableFeatures,
  useTable,
} from "@tanstack/react-table"
import type { RowSelectionState, SortingState } from "@tanstack/react-table"
import { cn } from "cn"
import {
  ChevronLeftIcon,
  ChevronRightIcon,
  DatabaseIcon,
  MoreVerticalIcon,
  PlusIcon,
} from "lucide-react"
import { useLocale } from "react-aria-components"

import { Badge } from "@tecton/react/components/badge"
import { Button } from "@tecton/react/components/button"
import { Checkbox } from "@tecton/react/components/checkbox"
import {
  DropdownMenu,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@tecton/react/components/dropdown-menu"
import {
  Empty,
  EmptyContent,
  EmptyDescription,
  EmptyHeader,
  EmptyMedia,
  EmptyTitle,
} from "@tecton/react/components/empty"
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@tecton/react/components/select"
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@tecton/react/components/table"

import { formatDate, statusMeta, typeMeta } from "../data"
import type { Well } from "../data"

// TanStack Table v9: declare the features the wells table uses.
const features = tableFeatures({
  rowPaginationFeature,
  rowSelectionFeature,
  rowSortingFeature,
  paginatedRowModel: createPaginatedRowModel(),
  sortedRowModel: createSortedRowModel(),
})

const columns = createColumnHelper<typeof features, Well>()

/** A number in the reader's locale (React Aria `I18nProvider`, else the browser). */
function LocaleNumber({
  value,
  ...props
}: React.ComponentProps<"span"> & { value: number }) {
  const { locale } = useLocale()
  return <span {...props}>{value.toLocaleString(locale)}</span>
}

/** An ISO date in the reader's locale. */
function LocaleDate({
  value,
  ...props
}: React.ComponentProps<"span"> & { value: string }) {
  const { locale } = useLocale()
  return <span {...props}>{formatDate(value, locale)}</span>
}

function createWellColumns(onOpen?: (well: Well) => void) {
  return columns.columns([
    columns.display({
      id: "select",
      header: () => <Checkbox slot="selection" aria-label="Select all rows" />,
      cell: () => <Checkbox slot="selection" aria-label="Select row" />,
      enableSorting: false,
    }),
    columns.accessor("name", {
      header: "Well",
      cell: ({ getValue }) => (
        <span className="font-mono font-medium tabular-nums">{getValue()}</span>
      ),
    }),
    columns.accessor("field", { header: "Field" }),
    columns.accessor("type", {
      header: "Type",
      cell: ({ getValue }) => typeMeta[getValue()],
    }),
    columns.accessor("status", {
      header: "Status",
      cell: ({ getValue }) => {
        const meta = statusMeta[getValue()]
        return (
          <Badge variant={meta.color} appearance="outline">
            {meta.label}
          </Badge>
        )
      },
    }),
    columns.accessor("td", {
      header: "TD (m MD)",
      cell: ({ getValue }) => (
        <LocaleNumber
          value={getValue()}
          className="block text-end font-mono tabular-nums"
        />
      ),
    }),
    columns.accessor("spud", {
      header: "Spud",
      cell: ({ getValue }) => (
        <LocaleDate value={getValue()} className="font-mono tabular-nums" />
      ),
    }),
    columns.accessor("rig", { header: "Rig" }),
    columns.display({
      id: "actions",
      header: "",
      enableSorting: false,
      cell: ({ row }) => (
        <span className="flex justify-end">
          <DropdownMenuTrigger>
            <Button
              variant="ghost"
              size="icon-xs"
              aria-label={`Actions for ${row.original.name}`}
            >
              <MoreVerticalIcon />
            </Button>
            <DropdownMenu placement="bottom end">
              <DropdownMenuItem onAction={() => onOpen?.(row.original)}>
                Open
              </DropdownMenuItem>
              <DropdownMenuItem>Add to project</DropdownMenuItem>
              <DropdownMenuItem>Export logs</DropdownMenuItem>
              <DropdownMenuSeparator />
              <DropdownMenuItem variant="destructive">Archive</DropdownMenuItem>
            </DropdownMenu>
          </DropdownMenuTrigger>
        </span>
      ),
    }),
  ])
}

const pageSizeOptions = [10, 25, 50, 100]

type WellsTableProps = React.ComponentProps<"div"> & {
  data: Well[]
  onOpen?: ((well: Well) => void) | undefined
  /** Rows per page. */
  pageSize?: number
  onRowSelectionChange?: (selection: RowSelectionState) => void
}

/**
 * Paginated, sortable, selectable wells grid: TanStack Table state rendered
 * with the React Aria `Table` primitives. Cells stack into labelled rows on
 * narrow viewports.
 */
function WellsTable({
  className,
  data,
  onOpen,
  pageSize = 10,
  onRowSelectionChange,
  ...props
}: WellsTableProps) {
  const wellColumns = React.useMemo(() => createWellColumns(onOpen), [onOpen])
  const [sorting, setSorting] = React.useState<SortingState>([])
  const [rowSelection, setRowSelection] = React.useState<RowSelectionState>({})
  const [pagination, setPagination] = React.useState({ pageIndex: 0, pageSize })

  React.useEffect(() => {
    onRowSelectionChange?.(rowSelection)
  }, [rowSelection, onRowSelectionChange])

  const table = useTable({
    features,
    data,
    columns: wellColumns,
    getRowId: (row) => row.id,
    state: { sorting, rowSelection, pagination },
    onSortingChange: setSorting,
    onRowSelectionChange: setRowSelection,
    onPaginationChange: setPagination,
  })

  const rows = table.getRowModel().rows
  const [primarySort] = sorting
  const sortDirection: "ascending" | "descending" = primarySort?.desc
    ? "descending"
    : "ascending"
  const sortDescriptor = primarySort
    ? { column: primarySort.id, direction: sortDirection }
    : undefined

  return (
    <div
      data-slot="wells-table"
      className={cn(
        "flex w-full flex-col overflow-hidden rounded-md border bg-card text-sm",
        className
      )}
      {...props}
    >
      <Table
        aria-label="Wells"
        selectionMode="multiple"
        selectedKeys={table.getSelectedRowModel().rows.map((row) => row.id)}
        onSelectionChange={(selection) => {
          if (selection === "all") {
            table.toggleAllRowsSelected(true)
          } else {
            table.setRowSelection(
              Object.fromEntries(
                [...selection].map((key) => [String(key), true])
              )
            )
          }
        }}
        {...(sortDescriptor === undefined ? {} : { sortDescriptor })}
        onSortChange={(descriptor) =>
          table.setSorting([
            {
              id: String(descriptor.column),
              desc: descriptor.direction === "descending",
            },
          ])
        }
      >
        <TableHeader className="bg-muted max-md:sr-only [&_tr]:border-border-subtle">
          {table.getFlatHeaders().map((header) => (
            <TableHead
              key={header.id}
              id={header.id}
              isRowHeader={header.index === 1}
              allowsSorting={header.column.getCanSort()}
              className={cn(
                "h-11 px-3 text-xs",
                header.column.id === "select" && "w-10"
              )}
            >
              {header.isPlaceholder ? null : (
                <table.FlexRender header={header} />
              )}
            </TableHead>
          ))}
        </TableHeader>
        <TableBody
          renderEmptyState={() => (
            <div className="py-8 text-center text-muted-foreground">
              No results.
            </div>
          )}
          className="max-md:[&_td]:flex max-md:[&_td]:h-auto max-md:[&_td]:justify-between max-md:[&_td]:py-1.5 max-md:[&_td]:before:text-muted-foreground max-md:[&_td]:before:content-[attr(data-label)] [&_tr]:border-border-subtle max-md:[&_tr]:flex max-md:[&_tr]:flex-col max-md:[&_tr]:py-2 [&_tr:nth-child(even)]:bg-surface-alt/60"
        >
          {rows.map((row) => (
            <TableRow
              key={row.id}
              id={row.id}
              onAction={() => onOpen?.(row.original)}
              className="hover:bg-accent/60 data-selected:bg-accent"
            >
              {row.getAllCells().map((cell) => (
                <TableCell
                  key={cell.id}
                  data-label={
                    typeof cell.column.columnDef.header === "string"
                      ? cell.column.columnDef.header
                      : undefined
                  }
                  className={cn(
                    "h-11 px-3",
                    cell.column.id === "select" && "w-10"
                  )}
                >
                  <table.FlexRender cell={cell} />
                </TableCell>
              ))}
            </TableRow>
          ))}
        </TableBody>
      </Table>
      <div
        data-slot="wells-table-footer"
        className="flex items-center justify-between gap-3 border-t bg-muted/60 px-3 py-1.5 text-xs text-muted-foreground"
      >
        <span className="tabular-nums">
          {table.getSelectedRowModel().rows.length} of{" "}
          {table.getPrePaginatedRowModel().rows.length} selected
        </span>
        <div className="ms-auto flex items-center gap-3">
          <div className="flex items-center gap-1.5">
            <span>Rows per page</span>
            <Select
              aria-label="Rows per page"
              value={String(pagination.pageSize)}
              onChange={(key) => table.setPageSize(Number(key))}
            >
              <SelectTrigger size="sm" className="h-7 w-18 text-xs">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                {pageSizeOptions.map((size) => (
                  <SelectItem
                    key={size}
                    id={String(size)}
                    textValue={String(size)}
                  >
                    {size}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>
          <span className="tabular-nums">
            Page {pagination.pageIndex + 1} of{" "}
            {Math.max(1, table.getPageCount())}
          </span>
          <div className="flex items-center">
            <Button
              variant="ghost"
              size="icon-xs"
              aria-label="Previous page"
              onPress={() => table.previousPage()}
              isDisabled={!table.getCanPreviousPage()}
            >
              <ChevronLeftIcon className="rtl:rotate-180" />
            </Button>
            <Button
              variant="ghost"
              size="icon-xs"
              aria-label="Next page"
              onPress={() => table.nextPage()}
              isDisabled={!table.getCanNextPage()}
            >
              <ChevronRightIcon className="rtl:rotate-180" />
            </Button>
          </div>
        </div>
      </div>
    </div>
  )
}

type WellsEmptyStateProps = React.ComponentProps<typeof Empty> & {
  /** True when a filter is active (offers "clear filters" instead of "add well"). */
  filtered?: boolean
  onClear?: () => void
  onCreate?: () => void
}

function WellsEmptyState({
  className,
  filtered = false,
  onClear,
  onCreate,
  ...props
}: WellsEmptyStateProps) {
  return (
    <Empty
      data-slot="wells-empty-state"
      className={cn(
        "rounded-md border border-dashed border-border bg-card/50",
        className
      )}
      {...props}
    >
      <EmptyHeader>
        <EmptyMedia variant="icon">
          <DatabaseIcon />
        </EmptyMedia>
        <EmptyTitle>{filtered ? "No wells match" : "No wells yet"}</EmptyTitle>
        <EmptyDescription>
          {filtered
            ? "Try a different search term, or clear the field, type and status filters."
            : "Import wells from the corporate database or create the first planned well."}
        </EmptyDescription>
      </EmptyHeader>
      <EmptyContent className="flex-row justify-center">
        {filtered ? (
          <Button
            variant="outline"
            size="sm"
            {...(onClear === undefined ? {} : { onPress: onClear })}
          >
            Clear filters
          </Button>
        ) : (
          <>
            <Button variant="outline" size="sm">
              Import
            </Button>
            <Button
              size="sm"
              {...(onCreate === undefined ? {} : { onPress: onCreate })}
            >
              <PlusIcon /> New well
            </Button>
          </>
        )}
      </EmptyContent>
    </Empty>
  )
}

export { WellsTable, WellsEmptyState, createWellColumns }
export type { WellsTableProps, WellsEmptyStateProps }

"use client"

import * as React from "react"
import { cn } from "cn"
import { DownloadIcon, PlusIcon, UploadIcon } from "lucide-react"

import { Button } from "@tecton/react/components/button"
import {
  PageHeader,
  PageHeaderActions,
  PageHeaderContent,
  PageHeaderDescription,
  PageHeaderEyebrow,
  PageHeaderTitle,
} from "@tecton/react/tecton/page-header"

import { emptyFilter, WellsFilterBar } from "./components/wells-filter-bar"
import type { WellsFilter } from "./components/wells-filter-bar"
import { WellsEmptyState, WellsTable } from "./components/wells-table"
import { wells as allWells } from "./data"
import type { Well } from "./data"

type WellsListPageProps = React.ComponentProps<"div"> & {
  wells?: Well[]
  /** Render the empty-state variant (no wells at all). */
  empty?: boolean
  onOpen?: (well: Well) => void
}

function applyFilter(wells: Well[], filter: WellsFilter): Well[] {
  const query = filter.query.trim().toLowerCase()
  return wells.filter((well) => {
    if (filter.field !== "all" && well.field !== filter.field) return false
    if (filter.type !== "all" && well.type !== filter.type) return false
    if (filter.statuses.length > 0 && !filter.statuses.includes(well.status))
      return false
    if (
      query &&
      ![well.name, well.rig, well.operator, well.field].some((text) =>
        text.toLowerCase().includes(query)
      )
    )
      return false
    return true
  })
}

/**
 * Wells list page — page header with actions, a filter bar (search,
 * selects, status chips) and a paginated, selectable TanStack `Table`, with
 * an empty state for no data / no matches.
 */
function WellsListPage({
  className,
  wells = allWells,
  empty = false,
  onOpen,
  ...props
}: WellsListPageProps) {
  const [filter, setFilter] = React.useState<WellsFilter>(emptyFilter)
  const source = empty ? [] : wells
  const rows = React.useMemo(
    () => applyFilter(source, filter),
    [source, filter]
  )
  const filtered = JSON.stringify(filter) !== JSON.stringify(emptyFilter)

  return (
    <div
      data-slot="wells-list-page"
      className={cn(
        "flex min-h-svh w-full flex-col gap-6 bg-background px-4 py-8 text-foreground md:px-8",
        className
      )}
      {...props}
    >
      <PageHeader>
        <PageHeaderContent>
          <PageHeaderEyebrow>Inventory</PageHeaderEyebrow>
          <PageHeaderTitle>Wells</PageHeaderTitle>
          <PageHeaderDescription>
            All wells across your licences. Select rows to add them to a project
            or export their logs.
          </PageHeaderDescription>
        </PageHeaderContent>
        <PageHeaderActions>
          <Button variant="ghost" size="sm">
            <DownloadIcon /> Export
          </Button>
          <Button variant="outline" size="sm">
            <UploadIcon /> Import
          </Button>
          <Button size="sm">
            <PlusIcon /> New well
          </Button>
        </PageHeaderActions>
      </PageHeader>

      {source.length > 0 && (
        <WellsFilterBar
          value={filter}
          onChange={setFilter}
          resultCount={rows.length}
        />
      )}

      {rows.length === 0 ? (
        <WellsEmptyState
          filtered={source.length > 0 && filtered}
          onClear={() => setFilter(emptyFilter)}
        />
      ) : (
        <WellsTable data={rows} onOpen={onOpen} />
      )}
    </div>
  )
}

/** Route-ready page. */
export default function WellsListRoute() {
  return <WellsListPage />
}

export {
  WellsListPage,
  WellsFilterBar,
  WellsTable,
  WellsEmptyState,
  applyFilter,
}
export { wells, statusMeta, typeMeta, fields, formatDate } from "./data"
export { emptyFilter } from "./components/wells-filter-bar"
export type { WellsListPageProps }
export type { WellsFilter } from "./components/wells-filter-bar"
export type { Well, WellStatus, WellType } from "./data"
